// static
bool PageStubDispatch::Accept(
    Page* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kPage_OnProgressUpdate_Name: {

      DCHECK(message->is_serialized());
      internal::Page_OnProgressUpdate_Params_Data* params =
          reinterpret_cast<internal::Page_OnProgressUpdate_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      double p_progress_fraction{};
      std::string p_label{};
      Page_OnProgressUpdate_ParamsDataView input_data_view(params, message);
      
      if (success)
        p_progress_fraction = input_data_view.progress_fraction();
      if (success && !input_data_view.ReadLabel(&p_label))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnProgressUpdate(
std::move(p_progress_fraction), 
std::move(p_label));
      return true;
    }
    case internal::kPage_OnInstallFinished_Name: {

      DCHECK(message->is_serialized());
      internal::Page_OnInstallFinished_Params_Data* params =
          reinterpret_cast<internal::Page_OnInstallFinished_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      ::borealis::mojom::InstallResult p_error{};
      Page_OnInstallFinished_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadError(&p_error))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnInstallFinished(
std::move(p_error));
      return true;
    }
    case internal::kPage_RequestClose_Name: {

      DCHECK(message->is_serialized());
      internal::Page_RequestClose_Params_Data* params =
          reinterpret_cast<internal::Page_RequestClose_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      Page_RequestClose_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 2, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->RequestClose();
      return true;
    }
  }
  return false;
}

